//! Read-only Epoch reads against the TS fixtures (CoNET-SI 215afb18, generated by
//! tests/fixtures/epoch_readonly_gen/gen-epoch-fixtures.mjs with the pinned ethers 6.17.0).
//! In-process loopback stubs only; no network, no writes, no restarts.
mod common;

use alloy_primitives::U256;
use common::Answer;
use conet_node::chain::Rpc;
use conet_node::epoch::{
    checks_this_block, current_rate, decode_current_info, decode_restart_block, read_current_info,
    read_restart_block, restart_advice, validator_matches, validator_message, validator_signer,
    RestartAdvice, EPOCH_INFO_ADDR, NODE_RESTART_ADDR,
};
use serde_json::{json, Value};
use std::sync::{Arc, Mutex};

const FIXTURE: &str = include_str!("fixtures/epoch_readonly.json");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("fixture is JSON")
}

fn hex_bytes(s: &str) -> Vec<u8> {
    hex::decode(s.trim_start_matches("0x")).expect("fixture hex")
}

fn u(s: &str) -> U256 {
    U256::from_str_radix(s, 10).expect("decimal fixture value")
}

#[test]
fn current_info_decodes_to_the_ts_fixture_values() {
    let fx = fixture();
    for case in fx["currentInfo"].as_array().unwrap() {
        let info = decode_current_info(&hex_bytes(case["returndata"].as_str().unwrap()))
            .unwrap_or_else(|e| panic!("{}: {e}", case["name"]));
        let e = &case["expect"];
        assert_eq!(
            info.epoch,
            u(e["epoch"].as_str().unwrap()),
            "{}",
            case["name"]
        );
        assert_eq!(
            info.total_miners,
            u(e["totalMiners"].as_str().unwrap()),
            "{}",
            case["name"]
        );
        assert_eq!(
            info.miner_rate,
            u(e["minerRateWei"].as_str().unwrap()),
            "{}",
            case["name"]
        );
        assert_eq!(
            info.total_usrs,
            u(e["totalUsrs"].as_str().unwrap()),
            "{}",
            case["name"]
        );
    }
}

#[test]
fn restart_block_decodes_to_the_ts_fixture_values() {
    let fx = fixture();
    for case in fx["restartBlockNumber"].as_array().unwrap() {
        let v = decode_restart_block(&hex_bytes(case["returndata"].as_str().unwrap())).unwrap();
        assert_eq!(
            v,
            u(case["expect"]["restartBlockNumber"].as_str().unwrap()),
            "{}",
            case["name"]
        );
    }
}

#[test]
fn a_short_or_garbage_return_is_an_error_not_a_default() {
    assert!(decode_current_info(&[]).is_err());
    assert!(decode_current_info(&[0u8; 31]).is_err());
    assert!(decode_restart_block(&[0u8; 5]).is_err());
}

/// Loopback node: `eth_getCode` answers `code` for the restart contract, and `eth_call` answers the
/// fixture return data per target address. Records every method called.
async fn epoch_node(code: &'static str, calls: Arc<Mutex<Vec<String>>>) -> String {
    let fx = fixture();
    let info = fx["currentInfo"][0]["returndata"]
        .as_str()
        .unwrap()
        .to_string();
    let restart = fx["restartBlockNumber"][1]["returndata"]
        .as_str()
        .unwrap()
        .to_string();
    let answer: Answer = Arc::new(move |method: &str, params: &Value| {
        calls.lock().unwrap().push(method.to_string());
        match method {
            "eth_getCode" => {
                assert_eq!(
                    params[0].as_str().unwrap().to_ascii_lowercase(),
                    NODE_RESTART_ADDR
                );
                json!(code)
            }
            "eth_call" => {
                let to = params[0]["to"].as_str().unwrap().to_ascii_lowercase();
                if to == EPOCH_INFO_ADDR {
                    json!(info)
                } else if to == NODE_RESTART_ADDR {
                    json!(restart)
                } else {
                    panic!("unexpected eth_call target {to}")
                }
            }
            other => panic!("unexpected method {other}"),
        }
    });
    common::serve(answer).await
}

#[tokio::test]
async fn reads_current_info_from_the_epoch_contract_only() {
    let calls = Arc::new(Mutex::new(vec![]));
    let url = epoch_node("0x6080", calls.clone()).await;
    let rpc = Rpc::new(&url).unwrap();
    let fx = fixture();
    let want = &fx["currentInfo"][0]["expect"];
    let got = read_current_info(&rpc).await.unwrap();
    assert_eq!(got.epoch, u(want["epoch"].as_str().unwrap()));
    assert_eq!(got.total_miners, u(want["totalMiners"].as_str().unwrap()));
    assert_eq!(calls.lock().unwrap().as_slice(), ["eth_call"]);
}

#[tokio::test]
async fn restart_block_is_none_when_the_contract_has_no_code() {
    let calls = Arc::new(Mutex::new(vec![]));
    let url = epoch_node("0x", calls.clone()).await;
    let rpc = Rpc::new(&url).unwrap();
    assert_eq!(read_restart_block(&rpc).await.unwrap(), None);
    // TS returns before reading restartBlockNumber when there is no code.
    assert_eq!(calls.lock().unwrap().as_slice(), ["eth_getCode"]);
}

#[tokio::test]
async fn restart_block_is_read_when_the_contract_has_code() {
    let calls = Arc::new(Mutex::new(vec![]));
    let url = epoch_node("0x6080", calls.clone()).await;
    let rpc = Rpc::new(&url).unwrap();
    let fx = fixture();
    let want = u(fx["restartBlockNumber"][1]["expect"]["restartBlockNumber"]
        .as_str()
        .unwrap());
    assert_eq!(read_restart_block(&rpc).await.unwrap(), Some(want));
}

#[test]
fn restart_advice_matches_the_ts_branches_and_never_acts() {
    use RestartAdvice::*;
    assert_eq!(restart_advice(None, None), NoContract);
    assert_eq!(restart_advice(Some(0), None), NoContract);
    assert_eq!(restart_advice(None, Some(U256::ZERO)), Nothing);
    assert_eq!(restart_advice(Some(0), Some(U256::ZERO)), Nothing);
    // TS: chain says 0, saved setup 77553 (stale): reset to 0.
    assert_eq!(
        restart_advice(Some(77_553), Some(U256::ZERO)),
        ClearStaleSetup
    );
    // TS: chain has a newer restart block than the saved setup: upgrade and reboot (not run here).
    assert_eq!(
        restart_advice(Some(10), Some(U256::from(26_000_000u64))),
        RestartRequired {
            to: U256::from(26_000_000u64)
        }
    );
    // Already recorded, or no saved setup: nothing.
    assert_eq!(
        restart_advice(Some(26_000_000), Some(U256::from(26_000_000u64))),
        Nothing
    );
    assert_eq!(
        restart_advice(None, Some(U256::from(26_000_000u64))),
        Nothing
    );
}

#[test]
fn current_rate_is_recorded_only_for_a_positive_epoch_and_even_blocks_only() {
    let fx = fixture();
    let zero = decode_current_info(&hex_bytes(
        fx["currentInfo"][1]["returndata"].as_str().unwrap(),
    ))
    .unwrap();
    let live = decode_current_info(&hex_bytes(
        fx["currentInfo"][0]["returndata"].as_str().unwrap(),
    ))
    .unwrap();
    assert!(current_rate(&zero).is_none());
    let r = current_rate(&live).expect("epoch > 0");
    assert_eq!(r.epoch, live.epoch);
    assert!(checks_this_block(10));
    assert!(!checks_this_block(11));
}

#[test]
fn validator_message_and_signer_match_the_ts_fixtures() {
    let fx = fixture();
    for case in fx["validatorMining"].as_array().unwrap() {
        let msg: Value = serde_json::from_str(case["message"].as_str().unwrap()).unwrap();
        let epoch = msg["epoch"].as_str().unwrap();
        let wallet = msg["wallet"].as_str().unwrap();
        assert_eq!(
            validator_message(epoch, wallet).unwrap(),
            case["message"].as_str().unwrap(),
            "{}: message bytes",
            case["name"]
        );
        let signer = validator_signer(epoch, wallet, case["hash"].as_str().unwrap()).unwrap();
        assert_eq!(
            signer,
            case["expect"]["nodeWallet"].as_str().unwrap(),
            "{}: signer",
            case["name"]
        );
    }
}

#[test]
fn a_changed_epoch_recovers_a_different_wallet_so_the_check_fails() {
    let fx = fixture();
    let cases = fx["validatorMining"].as_array().unwrap();
    let base = &cases[0];
    let changed = cases.last().unwrap();
    let msg: Value = serde_json::from_str(base["message"].as_str().unwrap()).unwrap();
    let wallet = msg["wallet"].as_str().unwrap();
    let node = base["expect"]["nodeWallet"].as_str().unwrap();
    assert!(validator_matches(
        msg["epoch"].as_str().unwrap(),
        wallet,
        base["hash"].as_str().unwrap(),
        node
    )
    .unwrap());
    // Epoch 6 with the epoch-5 hash recovers another address (fixture case).
    let got = validator_signer("6", wallet, base["hash"].as_str().unwrap()).unwrap();
    assert_eq!(got, changed["expect"]["nodeWallet"].as_str().unwrap());
    assert_ne!(got, node);
    assert!(!validator_matches("6", wallet, base["hash"].as_str().unwrap(), node).unwrap());
}

#[test]
fn validator_inputs_fail_closed() {
    let w = "0x1111111111111111111111111111111111111111";
    assert!(validator_message("", w).is_err());
    assert!(validator_message("-1", w).is_err());
    assert!(validator_message("0x5", w).is_err());
    assert!(validator_message("5", "not-an-address").is_err());
    assert!(validator_signer("5", w, "0x1234").is_err());
}
